import{_ as o,l,o as e,c as n,v as r,p as i,x as t,d as E,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"SPEC 与基准陷阱","description":"","frontmatter":{"title":"SPEC 与基准陷阱","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/spec-benchmark-pitfalls.md","filePath":"cs/spec-benchmark-pitfalls.md","lastUpdated":1789023840000}'),d={name:"cs/spec-benchmark-pitfalls.md"};function P(h,a,m,A,S,C){const s=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="spec-与基准陷阱" tabindex="-1">SPEC 与基准陷阱 <a class="header-anchor" href="#spec-与基准陷阱" aria-label="Permalink to &quot;SPEC 与基准陷阱&quot;">​</a></h1><div class="epigraph"><p>分数是在规定输入、规定规则下的时间比；换编译器、开不准的旗、只跑热缓存的子集，都可以让数字动，而不代表你的负载会动。</p><footer>—— 据 SPEC CPU 基准文档；Hennessy and Patterson, CA:AQA 对基准的讨论 整理</footer></div><p><a href="/cs/strong-weak-scaling">上一课</a> 要求声明规模。工业界常用 SPEC CPU、SPECrate、SPECpower 给微结构打分。本课不重画扩展曲线。缺口是 <strong>基准规则与常见作弊/误读：训练集过大、峰值频率、只测吞吐不测延迟。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>微结构论文用 SPEC 证明 <a href="/cs/tage-predictor">TAGE</a> 或 <a href="/cs/rrip-dead-block">RRIP</a> 有效，这合理。把分数当成「任意服务器快多少」不合理：输入固定（偏 Amdahl/强），工作集未必像你的数据库。缺口不是否定 SPEC，而是<strong>读分数时核对：基线编译器、峰值 vs 持续频率、rate（吞吐多副本）还是 speed（单问题时间）。</strong></p><p><span class="marginnote">Hennessy–Patterson 反复强调：用真实负载、报告几何平均、警惕峰值。SPEC 禁止针对基准的源码改动（规则随版本），但仍允许编译选项在范围内优化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读报告：speed 还是 rate；整数还是浮点；能耗。对照自己的 <a href="/cs/mlp-memory-parallelism">MLP</a> 与分支密度是否同类。微基准（只测延迟、只测带宽） complementary，不能替代。模拟器下一课 gem5 用 SPEC 子集时更要防「只跑 100M 指令的暖机幻觉」。</p>',8)),(e(),i(c,null,{default:t(()=>[p(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPEC%5B%22SPEC%20%E5%88%86%E6%95%B0%22%5D%20--%3E%20RULE%5B%22%E8%BE%93%E5%85%A5%E4%B8%8E%E8%A7%84%E5%88%99%E5%9B%BA%E5%AE%9A%22%5D%0A%20%20SPEC%20--%3E%20MIS%5B%22%E4%B8%8D%E7%AD%89%E4%BA%8E%E4%BD%A0%E7%9A%84%20NUMA%20%E6%95%B0%E6%8D%AE%E5%BA%93%22%5D%0A%20%20RATE%5B%22SPECrate%22%5D%20--%3E%20TP%5B%22%E5%A4%9A%E5%89%AF%E6%9C%AC%E5%90%9E%E5%90%90%22%5D%0A%20%20SPEED%5B%22SPECspeed%22%5D%20--%3E%20LAT%5B%22%E5%8D%95%E5%AE%9E%E4%BE%8B%E6%97%B6%E9%97%B4%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>编译器把 <a href="/cs/macro-micro-fusion">宏融合</a> 与向量化吃满，分数涨，ISA 没变。频率：睿频让短跑很高，TDP 墙让长跑掉下来——与 <a href="/cs/deep-pipeline-clock">深流水功耗</a> 一致。基准陷阱是测量方法，不是某条微结构定理。</p><p>几何平均会掩盖「某一个子程序崩了」：某个 SPECfp 子项吃内存带宽，总分仍可被其他子项拉回。读分要看单项，尤其当你的负载只像其中一两个子项时。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 SPEC 套件版本列成表。PMU 下一课才是「在自己的负载上看事件」，比迷信总分更有用。Roofline 再下一课给「算力墙还是带宽墙」一张图。</p><p>后课默认：基准分数有规则；解释自己的程序要用计数器与模型。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SPEC 是受控比较，不是工作负载的充分统计。</li><li>rate/speed、编译器、频率墙都会改数字。</li><li>性能计数器把测量搬到你的二进制上，下一课。</li><li>出处：SPEC 文档；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const B=o(d,[["render",P]]);export{_ as __pageData,B as default};
